function formatModelBytes(bytes) {
  if (!Number.isFinite(bytes) || bytes <= 0)
    return "";
  if (bytes >= 1e9)
    return `${(bytes / 1e9).toFixed(1)} GB`;
  return `${Math.round(bytes / 1e6)} MB`;
}

